import React from 'react';
import { Card, Table } from 'react-bootstrap';

const FilePreview = ({ previewData, headers }) => {
  if (!previewData || previewData.length === 0) {
    return null;
  }

  // Limit the number of columns to display to avoid overflow
  const maxColumns = 8;
  const displayHeaders = headers.slice(0, maxColumns);
  const showMore = headers.length > maxColumns;

  return (
    <Card className="mb-4">
      <Card.Body>
        <Card.Title>File Preview</Card.Title>
        <Card.Text>
          Showing the first {previewData.length} rows of your file.
        </Card.Text>

        <div className="table-responsive">
          <Table size="sm" bordered hover>
            <thead>
              <tr>
                {displayHeaders.map((header, idx) => (
                  <th key={idx}>{header}</th>
                ))}
                {showMore && <th>...</th>}
              </tr>
            </thead>
            <tbody>
              {previewData.map((row, rowIdx) => (
                <tr key={rowIdx}>
                  {row.slice(0, maxColumns).map((cell, cellIdx) => (
                    <td key={cellIdx}>{cell}</td>
                  ))}
                  {showMore && <td>...</td>}
                </tr>
              ))}
            </tbody>
          </Table>
        </div>
      </Card.Body>
    </Card>
  );
};

export default FilePreview;
